def parse_file(depot, path):
    b = read_bytes(path)
    if depot == "central":
        return parse_central(b)
    text = decode(b)
    if depot == "north":
        return parse_north(text)
    if depot == "south":
        return parse_south(text)
    if depot in DELIMITED:
        return parse_delimited(depot, text)
    warn("no parser for depot %r (%s)" % (depot, path))
    return None, []


def main(data_dir, out_file):
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-", 1)[0]
        try:
            seq, recs = parse_file(depot, path)
        except Exception as e:  # noqa
            warn("failed to read %s: %r" % (name, e))
            seq, recs = None, []
