    corrections = 0
    resends = 0
    current = {}
    for depot, files in exports.items():
        cur = {}
        for seq, name, recs in sorted(files, key=lambda x: (x[0], x[1])):
            for r in recs:
                n = r["num"]
                if n is None:
                    continue
                if r["kind"] == "new":
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r["kind"] == "correction":
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur

    def rank(depot):
        return HANDOVER_ORDER.index(depot) if depot in HANDOVER_ORDER else len(HANDOVER_ORDER)

    owners = {}
    for depot in sorted(current, key=lambda d: (rank(d), d)):
        for n, r in current[depot].items():
            owners.setdefault(n, []).append((depot, r))
    handovers = sum(1 for v in owners.values() if len(v) > 1)

    depots = {d: [0, Decimal(0)] for d in exports}
    months = {}
    for n, lst in owners.items():
        depot, r = lst[0]
        if r["status"] not in ("delivered", "delivered_late"):
            continue
        depots[depot][0] += 1
        depots[depot][1] += r["kg"]
        if r["month"] is not None:
            m = months.setdefault(r["month"], [0, Decimal(0)])
            m[0] += 1
            m[1] += r["kg"]

    def fmt(x):
        return float(x.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))

    result = {
        "depots": {d: {"shipments": v[0], "total_kg": fmt(v[1])} for d, v in sorted(depots.items())},
        "months": {k: {"shipments": v[0], "total_kg": fmt(v[1])} for k, v in sorted(months.items())},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w", encoding="utf-8") as fh:
        json.dump(result, fh, indent=2)
        fh.write("\n")


if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("usage: summarize.py DATA_DIR OUT_FILE", file=sys.stderr)
        sys.exit(2)
    main(sys.argv[1], sys.argv[2])

